import { Kbd } from "@/registry/erbium/ui/kbd";

export default function KbdDemo() {
  return (
    <div className="flex flex-wrap items-center justify-center gap-related">
      <Kbd hotkey="Mod+Shift+K" />
      <Kbd hotkey="Mod+B" />
      <Kbd hotkey="Escape" />
    </div>
  );
}

import { HugeiconsIcon } from "@hugeicons/react";
import Search01Icon from "@hugeicons/core-free-icons/Search01Icon";

import { InputGroup, InputGroupAddon, InputGroupInput } from "@/registry/erbium/ui/input-group";
import { Kbd } from "@/registry/erbium/ui/kbd";

export default function KbdInputGroup() {
  return (
    <div className="flex w-full max-w-xs flex-col gap-section">
      <InputGroup>
        <InputGroupInput placeholder="Search..." />
        <InputGroupAddon>
          <HugeiconsIcon icon={Search01Icon} />
        </InputGroupAddon>
        <InputGroupAddon align="inline-end">
          <Kbd hotkey="Mod+K" />
        </InputGroupAddon>
      </InputGroup>
    </div>
  );
}

import { Button } from "@/registry/erbium/ui/button";
import { ButtonGroup } from "@/registry/erbium/ui/button-group";
import { Kbd } from "@/registry/erbium/ui/kbd";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/registry/erbium/ui/tooltip";

export default function KbdTooltip() {
  return (
    <div className="flex flex-wrap gap-group">
      <ButtonGroup>
        <Tooltip>
          <TooltipTrigger
            render={
              <Button size="sm" variant="outline">
                Save
              </Button>
            }
          />
          <TooltipContent>
            Save Changes <Kbd hotkey="S" />
          </TooltipContent>
        </Tooltip>
        <Tooltip>
          <TooltipTrigger
            render={
              <Button size="sm" variant="outline">
                Print
              </Button>
            }
          />
          <TooltipContent>
            Print Document <Kbd hotkey="Mod+P" />
          </TooltipContent>
        </Tooltip>
      </ButtonGroup>
    </div>
  );
}

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { Kbd } from "@/registry/erbium/ui/kbd";

import PlaygroundExample from "./variants/playground";

const PlaygroundSource = "import { Kbd } from \"@/registry/erbium/ui/kbd\";\nimport type * as React from \"react\";\n\nconst Example = (args: React.ComponentProps<typeof Kbd>) => <Kbd {...args} />;\n\nexport default Example;\n";

import OverviewExample from "./variants/overview";

const OverviewSource = "import Demo from \"../examples/kbd-demo\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <Demo />\n  </div>\n);\n\nexport default Example;\n";

import ButtonExample from "./variants/button";

const ButtonSource = "import ExampleKbdButton from \"../examples/kbd-button\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <ExampleKbdButton />\n  </div>\n);\n\nexport default Example;\n";

import TooltipExample from "./variants/tooltip";

const TooltipSource = "import ExampleKbdTooltip from \"../examples/kbd-tooltip\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <ExampleKbdTooltip />\n  </div>\n);\n\nexport default Example;\n";

import InputGroupExample from "./variants/input-group";

const InputGroupSource = "import ExampleKbdInputGroup from \"../examples/kbd-input-group\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <ExampleKbdInputGroup />\n  </div>\n);\n\nexport default Example;\n";

const meta = {
  component: Kbd,
  tags: ["autodocs"],
  parameters: {
    layout: "centered",
    docs: {
      description: {
        component: "## Usage\n\nDisplays a platform-aware shortcut. Pass the stored binding to `hotkey`; TanStack Hotkeys formats it for macOS, Windows, or Linux.\n\n**Import:** `@/registry/erbium/ui/kbd`\n\n```tsx\n<Kbd hotkey=\"Mod+K\" />\n```\n\n## External documentation\n\nTanStack Hotkeys supplies platform detection and keyboard shortcut formatting.\n\n- [TanStack Hotkeys](https://tanstack.com/hotkeys/latest/docs/reference)",
      },
    },
  },
} satisfies Meta<typeof Kbd>;

export default { ...meta, title: "Components/Kbd",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<typeof Kbd> = {
  args: { hotkey: "Mod+K", className: "" },
  argTypes: {},
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: PlaygroundSource },
    },
  },
  render: PlaygroundExample,
};

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

export const Button: Story = {
  parameters: {
    docs: {
      description: { story: "Use `ButtonShortcut` for a platform-aware key hint with button spacing and RTL support." },
      source: { code: ButtonSource },
    },
  },
  render: ButtonExample,
};

export const Tooltip: Story = {
  parameters: {
    docs: {
      description: { story: "You can use the `Kbd` component inside a `Tooltip` component to display a tooltip with a keyboard key." },
      source: { code: TooltipSource },
    },
  },
  render: TooltipExample,
};

export const InputGroup: Story = {
  parameters: {
    docs: {
      description: { story: "You can use the `Kbd` component inside a `InputGroupAddon` component to display a keyboard key inside an input group." },
      source: { code: InputGroupSource },
    },
  },
  render: InputGroupExample,
};

